from solution import remove_whitespaces


def test_issue_example():
    """Remove all whitespaces: ' Google    Flutter ' becomes 'GoogleFlutter'."""
    assert remove_whitespaces(' Google    Flutter ') == 'GoogleFlutter'  # 1 leading + 4 middle + 1 trailing = 6 spaces removed


def test_issue_empty_string():
    """Remove all whitespaces from the given string with empty input stays empty."""
    assert remove_whitespaces('') == ''  # 0 chars - 0 whitespace = 0 chars


def test_issue_only_spaces():
    """Remove all whitespaces from a string of only spaces gives empty string."""
    assert remove_whitespaces('   ') == ''  # 3 spaces - 3 spaces = 0 chars


def test_issue_no_whitespace():
    """Remove all whitespaces leaves a string with no whitespace unchanged."""
    assert remove_whitespaces('GoogleFlutter') == 'GoogleFlutter'  # 13 chars - 0 whitespace = 13 chars


def test_issue_leading_trailing_spaces():
    """Remove all whitespaces including leading and trailing spaces."""
    assert remove_whitespaces('  abc  ') == 'abc'  # 2 leading + 2 trailing = 4 spaces removed


def test_issue_tabs_between_words():
    """Remove all whitespaces includes tab characters."""
    assert remove_whitespaces('a\tb\tc') == 'abc'  # 3 letters + 2 tabs - 2 tabs = 3 letters


def test_issue_newlines_between_words():
    """Remove all whitespaces includes newline characters."""
    assert remove_whitespaces('a\nb\nc') == 'abc'  # 3 letters + 2 newlines - 2 newlines = 3 letters


def test_issue_mixed_space_tab_newline():
    """Remove all whitespaces handles mixed spaces, tabs and newlines."""
    assert remove_whitespaces('a \t\nb') == 'ab'  # 1 space + 1 tab + 1 newline = 3 removed, 2 kept


def test_issue_other_whitespace_chars():
    """Remove all whitespaces includes carriage-return, form-feed and vertical-tab."""
    assert remove_whitespaces('a\rb\fc\vd') == 'abcd'  # 1 CR + 1 FF + 1 VT = 3 removed, 4 kept


def test_contract_preserves_punctuation():
    """Remove only whitespaces and must not remove punctuation."""
    assert remove_whitespaces('Hello, World!') == 'Hello,World!'  # 1 space removed from 13 chars = 12 chars


def test_contract_preserves_digits():
    """Remove only whitespaces and must not remove digits."""
    assert remove_whitespaces('123 456') == '123456'  # 6 digits + 1 space - 1 space = 6 digits


def test_contract_preserves_case():
    """Remove only whitespaces and must not change letter case."""
    assert remove_whitespaces('Ab C dE') == 'AbCdE'  # 2 spaces removed from 7 chars = 5 chars
